/*
 * A183124  Magnetic Tower of Hanoi, number of moves of disk number n,
 *          generated by a certain algorithm, yielding a "forward moving"
 *          non-optimal solution of the [NEUTRAL ; NEUTRAL ; NEUTRAL]
 *          pre-colored puzzle.
 * https://oeis.org/A183124
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = 4*a(n-1) - 2*a(n-2) - 4*a(n-3) + 3*a(n-4) for n ≥ 9
 *            Initial values: a(0)=0, a(1)=1, a(2)=3, a(3)=7, a(4)=19,
 *            a(5)=53, a(6)=153, a(7)=451, a(8)=1339
 * Range:     u8 n <= 6, u16 n <= 11, u32 n <= 21, u64 n <= 41, u128 n <= 82,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* first nine terms, indices 0..8 */
    static const seq_t init[9] = {
        (seq_t)0, (seq_t)1, (seq_t)3, (seq_t)7,
        (seq_t)19, (seq_t)53, (seq_t)153, (seq_t)451,
        (seq_t)1339
    };

    /* Return a precomputed term if n < 9 */
    if (n < 9)
        return init[n];

    /* Initialise the last four values needed for the recurrence:
       w = a(i-4), x = a(i-3), y = a(i-2), z = a(i-1) at the start of the loop. */
    seq_t w = init[5];   /* a(5) */
    seq_t x = init[6];   /* a(6) */
    seq_t y = init[7];   /* a(7) */
    seq_t z = init[8];   /* a(8) */
    seq_t next;

    for (idx_t i = 9; i <= n; ++i) {
        next = (seq_t)4 * z - (seq_t)2 * y - (seq_t)4 * x + (seq_t)3 * w;
        /* Shift the window for the next iteration */
        w = x;
        x = y;
        y = z;
        z = next;
    }

    return next;
}
